-- Introduce a distinct platform-level account classification for the existing Super Admin.
-- The privileged capability remains governed by internal_role and verified identity;
-- account_type alone never grants administrative permissions.
begin;

alter table public.bridge_profiles
  drop constraint if exists bridge_profiles_account_type_chk;

alter table public.bridge_profiles
  add constraint bridge_profiles_account_type_chk
  check (account_type = any (array[
    'independent_creator'::text,
    'studio'::text,
    'buyer'::text,
    'investor'::text,
    'platform_admin'::text
  ]));

do $migration$
declare
  matching_accounts integer;
begin
  select count(*) into matching_accounts
  from public.bridge_profiles
  where lower(trim(email)) = 'picturecrayons@gmail.com'
    and internal_role = 'super_admin'
    and email_verified = true;

  if matching_accounts <> 1 then
    raise exception 'Expected exactly one verified Super Admin profile for platform account classification; found %', matching_accounts;
  end if;

  update public.bridge_profiles
  set account_type = 'platform_admin',
      updated_at = now()
  where lower(trim(email)) = 'picturecrayons@gmail.com'
    and internal_role = 'super_admin'
    and email_verified = true;
end;
$migration$;

commit;

create or replace function public.bridge_loop_admin_set_featured(
  p_actor_user_id text,
  p_title_id uuid,
  p_featured boolean
)
returns void
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if auth.role() is distinct from 'service_role' then
    raise exception 'service role required';
  end if;

  if p_actor_user_id is null or p_title_id is null or p_featured is null then
    raise exception 'required arguments are missing';
  end if;

  if not exists (
    select 1
    from public.bridge_profiles p
    where p.user_id = p_actor_user_id
      and p.email_verified = true
      and p.internal_role in ('admin', 'super_admin')
  ) then
    raise exception 'verified Bridge admin identity required';
  end if;

  update public.loop_titles
  set featured = p_featured
  where id = p_title_id;

  if not found then
    raise exception 'LOOP title not found';
  end if;

  insert into public.bridge_audit_logs (
    actor_user_id, action, entity_type, entity_id, metadata
  ) values (
    p_actor_user_id,
    'loop.title.featured_updated',
    'loop_title',
    p_title_id::text,
    jsonb_build_object('featured', p_featured)::text
  );
end;
$function$;

revoke all on function public.bridge_loop_admin_set_featured(text, uuid, boolean) from public;
revoke all on function public.bridge_loop_admin_set_featured(text, uuid, boolean) from anon;
revoke all on function public.bridge_loop_admin_set_featured(text, uuid, boolean) from authenticated;
grant execute on function public.bridge_loop_admin_set_featured(text, uuid, boolean) to service_role;

alter function public.public_loop_catalog() security definer;
alter function public.public_loop_catalog() set search_path = '';
revoke all on function public.public_loop_catalog() from public;
revoke all on function public.public_loop_catalog() from anon;
revoke all on function public.public_loop_catalog() from authenticated;
grant execute on function public.public_loop_catalog() to anon;
